import{_ as t,C as n,o as s,c as i,a2 as a,G as l}from"./chunks/framework.BgSoyxN5.js";const k=JSON.parse('{"title":"Market Intelligence | Состояние рынка, а не новостная лента | TickerForge","description":"Рыночный режим, рыночный стресс, Fear & Greed, ротация секторов и экономическое здоровье США — пять регулярных чтений, которые говорят, в каких условиях находится рынок, а не какой заголовок только что вышел.","frontmatter":{"title":"Market Intelligence | Состояние рынка, а не новостная лента | TickerForge","description":"Рыночный режим, рыночный стресс, Fear & Greed, ротация секторов и экономическое здоровье США — пять регулярных чтений, которые говорят, в каких условиях находится рынок, а не какой заголовок только что вышел.","aside":false,"locale":"ru","alternateLocales":{"en":"/market-intelligence","ru":"/ru/market-intelligence"},"pageClass":"partners-page"},"headers":[],"relativePath":"ru/market-intelligence/index.md","filePath":"ru/market-intelligence/index.md","lastUpdated":1788187479000}'),o={name:"ru/market-intelligence/index.md"};function p(d,e,c,m,g,h){const r=n("PartnerChannelCta");return s(),i("div",null,[e[0]||(e[0]=a('<h1 id="market-intelligence" tabindex="-1">Market Intelligence <a class="header-anchor" href="#market-intelligence" aria-label="Permalink to &quot;Market Intelligence&quot;">​</a></h1><p>Пять регулярных чтений состояния рынка. Каждое отвечает на вопрос, на который новостная лента ответить не может.</p><p>Лента даёт <strong>события</strong>. Эти чтения дают <strong>состояние</strong> — названное условие, которое держится неделями, меняется редко и записывается при каждой смене, чтобы его можно было проверить потом.</p><div class="partners-hero-actions"><a class="partners-button partners-button--primary" href="/market-widget">Посмотреть текущее чтение</a><a class="partners-button partners-button--secondary" href="/ru/partners/market-news">Публиковать это в своём канале</a></div><p class="partners-locale-switch"><a href="/market-intelligence/" hreflang="en">Read this page in English</a></p><h2 id="разница-в-одну-строку" tabindex="-1">Разница в одну строку <a class="header-anchor" href="#разница-в-одну-строку" aria-label="Permalink to &quot;Разница в одну строку&quot;">​</a></h2><p>Заголовок сообщает, что S&amp;P упал на 1%. Он не может сказать, шум это внутри трендового рынка или подтверждение внутри хрупкого. Именно на этот вопрос и отвечают пять чтений ниже.</p><div class="partners-wide"><div class="partners-format-grid"><div class="partners-format partners-format--linked"><span>Неделя и день</span><strong><a href="/ru/market-intelligence/market-regime">Рыночный режим</a></strong><p>В каком из пяти состояний рынок сейчас — и отдельный алерт в те дни, когда состояние действительно сменилось.</p></div><div class="partners-format partners-format--linked"><span>Ежедневно</span><strong><a href="/ru/market-intelligence/market-stress">Рыночный стресс</a></strong><p>Давление по волатильности, кредиту и ставкам ослабевает, смешанное или растёт.</p></div><div class="partners-format partners-format--linked"><span>Ежедневно</span><strong><a href="/ru/market-intelligence/fear-and-greed">Fear &amp; Greed</a></strong><p>Не только уровень настроений, а направление их движения — половина, которую все остальные теряют.</p></div><div class="partners-format partners-format--linked"><span>День и неделя</span><strong><a href="/ru/market-intelligence/sector-rotation">Ротация секторов</a></strong><p>Какие сектора действительно ведут рынок, отдельно от тех, что просто растут вместе со всеми.</p></div><div class="partners-format partners-format--linked"><span>Ежемесячно</span><strong><a href="/ru/market-intelligence/economic-health">Экономическое здоровье США</a></strong><p>Один макро-композит из 20+ индикаторов — с разбором, что его держит и что тянет вниз.</p></div></div></div><h2 id="почему-это-не-сигналы" tabindex="-1">Почему это не сигналы <a class="header-anchor" href="#почему-это-не-сигналы" aria-label="Permalink to &quot;Почему это не сигналы&quot;">​</a></h2><p>Ни одно из этих чтений никому не говорит покупать или продавать. Они описывают условия. Что делать внутри этих условий — решение читателя, и в каждом посте это сказано прямо.</p><p>Именно поэтому их можно проверить. Канал, который каждую неделю пишет «на рынке волатильно», ни за что не отвечает. Чтение, которое называет состояние, ставит дату и сообщает о смене только когда состояние действительно сменилось, — отвечает.</p><h2 id="два-способа-этим-пользоваться" tabindex="-1">Два способа этим пользоваться <a class="header-anchor" href="#два-способа-этим-пользоваться" aria-label="Permalink to &quot;Два способа этим пользоваться&quot;">​</a></h2><div class="partners-wide partners-wide--compact"><ul class="partners-feature-list"><li><strong>Читать.</strong> Все пять выходят автоматической программой в публичном канале TickerForge, и у каждого есть своя карточка в боте.</li><li><strong>Публиковать.</strong> Одобренный партнёр в одно нажатие получает тот же пост со своей отслеживаемой ссылкой внутри — на английском или русском. Подробнее: <a href="/ru/partners/market-news">партнёры по рыночным новостям</a>.</li></ul></div>',13)),l(r),e[1]||(e[1]=a('<p>TickerForge — образовательное программное обеспечение для поддержки решений. Это не инвестиционная рекомендация, не сигнальный канал, не брокер и не обещание доходности.</p><h2 id="смежные-страницы" tabindex="-1">Смежные страницы <a class="header-anchor" href="#смежные-страницы" aria-label="Permalink to &quot;Смежные страницы&quot;">​</a></h2><ul><li><a href="/market-widget">Живой виджет рыночного режима</a></li><li><a href="/ru/partners/market-news">Партнёрская программа по рыночным новостям</a></li><li><a href="/methodology/">Методология</a></li><li><a href="/pricing">Тарифы TickerForge</a></li></ul>',3))])}const u=t(o,[["render",p]]);export{k as __pageData,u as default};
